const createSession = `-- name: CreateSession :one
insert into sessions (id, account_id, issued_ip, issued_ua)
values ($1, $2, nullif($3, '')::inet, nullif($4, ''))
returning id, account_id,
          coalesce(host(issued_ip), '') as issued_ip,
          coalesce(issued_ua, '') as issued_ua,
          issued_at, last_seen_at, revoked_at
`

type CreateSessionParams struct {
	ID        pgtype.UUID
	AccountID pgtype.UUID
	Column3   interface{}
	Column4   interface{}
}

type CreateSessionRow struct {
	ID         pgtype.UUID
	AccountID  pgtype.UUID
	IssuedIp   interface{}
	IssuedUa   string
	IssuedAt   pgtype.Timestamptz
	LastSeenAt pgtype.Timestamptz
	RevokedAt  pgtype.Timestamptz
}

// IAM-3 (ADR-039, issue #187 + #244 merged). One row per dashboard login.
// Caller has already generated the uuid (the envelope seal needs the same
// value). issued_ip is an inet (” cast to NULL means "RemoteAddr
// unparseable" — surfaced as "" on read by coalesce(host(...))).
func (q *Queries) CreateSession(ctx context.Context, db DBTX, arg CreateSessionParams) (CreateSessionRow, error) {
	row := db.QueryRow(ctx, createSession,
		arg.ID,
		arg.AccountID,
		arg.Column3,
		arg.Column4,
	)
	var i CreateSessionRow
	err := row.Scan(
		&i.ID,
		&i.AccountID,
		&i.IssuedIp,
		&i.IssuedUa,
		&i.IssuedAt,
		&i.LastSeenAt,
		&i.RevokedAt,
	)
	return i, err
}

const createTrigger = `-- name: CreateTrigger :one

insert into triggers (account_id, app_id, kind, slug, enabled, config,
                       batch_size_max, batch_window_ms, max_attempts,
                       cron_id, source, payload_max_bytes,
                       broker_poison_strategy)
values ($1, $2, $3, $4, $5, $6::jsonb, $7, $8, $9, $10, $11, $12, $13)
returning id, account_id, app_id, kind, slug, enabled, config,
          batch_size_max, batch_window_ms, max_attempts,
          cron_id, source, payload_max_bytes, broker_poison_strategy,
          created_at, updated_at
`

type CreateTriggerParams struct {
	AccountID            pgtype.UUID
	AppID                pgtype.UUID
	Kind                 string
	Slug                 string
	Enabled              bool
	Column6              []byte
	BatchSizeMax         int32
	BatchWindowMs        int32
	MaxAttempts          int32
	CronID               pgtype.UUID
	Source               pgtype.Text
	PayloadMaxBytes      int32
	BrokerPoisonStrategy string
}

type CreateTriggerRow struct {
	ID                   pgtype.UUID
	AccountID            pgtype.UUID
	AppID                pgtype.UUID
	Kind                 string
	Slug                 string
	Enabled              bool
	Config               []byte
	BatchSizeMax         int32
	BatchWindowMs        int32
	MaxAttempts          int32
	CronID               pgtype.UUID
	Source               pgtype.Text
	PayloadMaxBytes      int32
	BrokerPoisonStrategy string
	CreatedAt            pgtype.Timestamptz
	UpdatedAt            pgtype.Timestamptz
}

// Issue #757 / ADR-0NN — Trigger primitive (event-source mappings).
// Mirrors the cron `CreateCron` / `UpdateCron` / `DeleteCron` /
// `CronByID` / `ListCronsForApp` shape so the apid handler can stay
// symmetric with the existing cron surface. The dispatch tick
// (pkg/sched/dispatch_triggers.go, commit #14) writes
// ClaimTriggerRecords / MarkTriggerRecordSucceeded /
// MarkTriggerRecordRetry / MarkTriggerRecordDeadLetter, which the
// schedd uses under FOR UPDATE SKIP LOCKED to drain batches
// concurrently.
//
// The FOR UPDATE SKIP LOCKED on ClaimTriggerRecords mirrors the
// precedent set by ADR-099 PR-C's claim_job_tasks query (issue
// tracker 'job-task pull'): concurrent schedd replicas each claim
// disjoint row sets with no advisory-lock plumbing.
func (q *Queries) CreateTrigger(ctx context.Context, db DBTX, arg CreateTriggerParams) (CreateTriggerRow, error) {
	row := db.QueryRow(ctx, createTrigger,
		arg.AccountID,
		arg.AppID,
		arg.Kind,
		arg.Slug,
		arg.Enabled,
		arg.Column6,
		arg.BatchSizeMax,
		arg.BatchWindowMs,
		arg.MaxAttempts,
		arg.CronID,
		arg.Source,
		arg.PayloadMaxBytes,
		arg.BrokerPoisonStrategy,
	)
	var i CreateTriggerRow
	err := row.Scan(
		&i.ID,
		&i.AccountID,
		&i.AppID,
		&i.Kind,
		&i.Slug,
		&i.Enabled,
		&i.Config,
		&i.BatchSizeMax,
		&i.BatchWindowMs,
		&i.MaxAttempts,
		&i.CronID,
		&i.Source,
		&i.PayloadMaxBytes,
		&i.BrokerPoisonStrategy,
		&i.CreatedAt,
		&i.UpdatedAt,
	)
	return i, err
}

