const latestInstanceReadiness = `-- name: LatestInstanceReadiness :many
SELECT DISTINCT ON (CAST(data->>'instance_id' AS text))
       CAST(data->>'instance_id' AS text) AS instance_id,
       CAST(data->>'status' AS text) AS status,
       at,
       id
FROM events
WHERE kind IN ('wake.sidecar_health', 'wake.app_readiness')
  AND data->>'status' IN ('ready', 'unready')
  AND data->>'instance_id' = ANY($1::text[])
ORDER BY CAST(data->>'instance_id' AS text), at DESC, id DESC
`

type LatestInstanceReadinessRow struct {
	InstanceID string
	Status     string
	At         pgtype.Timestamptz
	ID         int64
}

// Gateway restart hydration: readiness is independent of the instance's
// RUNNING state, so replay only the latest reversible ready/unready event.
func (q *Queries) LatestInstanceReadiness(ctx context.Context, db DBTX, instanceIds []string) ([]LatestInstanceReadinessRow, error) {
	rows, err := db.Query(ctx, latestInstanceReadiness, instanceIds)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []LatestInstanceReadinessRow{}
	for rows.Next() {
		var i LatestInstanceReadinessRow
		if err := rows.Scan(
			&i.InstanceID,
			&i.Status,
			&i.At,
			&i.ID,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const latestInstanceReadinessBySource = `-- name: LatestInstanceReadinessBySource :many
SELECT DISTINCT ON (
           CAST(data->>'instance_id' AS text),
           CAST(CASE WHEN kind = 'wake.app_readiness' THEN 'primary_app'
                ELSE 'sidecar:' || CAST(data->>'sidecar_name' AS text) END AS text)
       )
       CAST(data->>'instance_id' AS text) AS instance_id,
       CAST(CASE WHEN kind = 'wake.app_readiness' THEN 'primary_app'
            ELSE 'sidecar:' || CAST(data->>'sidecar_name' AS text) END AS text) AS source,
       CAST(data->>'status' AS text) AS status,
       at,
       id
FROM events
WHERE kind IN ('wake.sidecar_health', 'wake.app_readiness')
  AND data->>'status' IN ('ready', 'unready')
  AND data->>'instance_id' = ANY($1::text[])
  AND (kind <> 'wake.sidecar_health' OR COALESCE(data->>'sidecar_name', '') <> '')
ORDER BY CAST(data->>'instance_id' AS text), source, at DESC, id DESC
`

type LatestInstanceReadinessBySourceRow struct {
	InstanceID string
	Source     string
	Status     string
	At         pgtype.Timestamptz
	ID         int64
}

// Gateway hydration keeps each required readiness source independent so one
// recovered probe cannot override another probe that is still unready.
func (q *Queries) LatestInstanceReadinessBySource(ctx context.Context, db DBTX, instanceIds []string) ([]LatestInstanceReadinessBySourceRow, error) {
	rows, err := db.Query(ctx, latestInstanceReadinessBySource, instanceIds)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []LatestInstanceReadinessBySourceRow{}
	for rows.Next() {
		var i LatestInstanceReadinessBySourceRow
		if err := rows.Scan(
			&i.InstanceID,
			&i.Source,
			&i.Status,
			&i.At,
			&i.ID,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const latestRetainedRollbackDeployment = `-- name: LatestRetainedRollbackDeployment :one
SELECT d.id FROM deployments d WHERE d.app_id=$1::uuid
AND NOT (d.canary_total_steps > 0 AND d.rollout_state = 'aborted' AND d.rollout_completed_at IS NULL)
AND ($2::text IS NULL OR d.scope=$2::text)
AND ($3::uuid IS NULL OR d.id<>$3::uuid)
AND (d.status='superseded' OR (d.status='live' AND d.traffic_percent=0 AND (
    d.serving_ended_at IS NOT NULL
    OR EXISTS(SELECT 1 FROM deployment_revision_pins p WHERE p.deployment_id=d.id AND p.expires_at>now())
    OR EXISTS(SELECT 1 FROM customer_operation_retained_deployment_refs retained WHERE retained.deployment_id=d.id))))
ORDER BY coalesce(d.serving_ended_at,d.created_at) DESC,d.created_at DESC,d.id DESC LIMIT 1
`

type LatestRetainedRollbackDeploymentParams struct {
	AppID               pgtype.UUID
	Scope               pgtype.Text
	CurrentDeploymentID pgtype.UUID
}

// Most recently serving first (serving_ended_at, migration
// 20261004234807528); rows superseded before it fall back to created_at.
// A live 0% deployment that served before (a release demoted by `traffic
// promote` or `traffic set`) is a rollback target; one that never served
// (a dark deploy) needs a retention pin. A canary candidate aborted before it
// ever completed served only its canary steps and failed them, so it is never
// an implicit target (H5-62).
func (q *Queries) LatestRetainedRollbackDeployment(ctx context.Context, db DBTX, arg LatestRetainedRollbackDeploymentParams) (pgtype.UUID, error) {
	row := db.QueryRow(ctx, latestRetainedRollbackDeployment, arg.AppID, arg.Scope, arg.CurrentDeploymentID)
	var id pgtype.UUID
	err := row.Scan(&id)
	return id, err
}

